const b = $input.item.json.body;
return [{
  json: {
    trip_id: b.trip_id,
    origin: b.origin,
    destination: b.destination,
    start_date: b.start_date,
    end_date: b.end_date,
    budget: b.budget,
    interests: b.interests || [],
    travelers: b.travelers || 1,
  }
}];

const j = $input.item.json;
const system = "You are the planning agent in a trip-planning system for Indian travelers. Given an origin, destination, date range and interests, produce a rough day-by-day skeleton. The ENTIRE trip takes place in and around the destination city only - do not route the traveler through other cities or plan stopovers elsewhere, even if a real-world road/rail route would pass through them. The first day covers arrival at the destination and the last day covers departure; every day in between must be themed around things to do inside the destination itself. Respond with ONLY JSON: {\"days\": [{\"date\": \"YYYY-MM-DD\", \"theme\": \"short theme\"}]}";
const user = `Origin: ${j.origin}\nDestination: ${j.destination}\nDates: ${j.start_date} to ${j.end_date}\nInterests: ${(j.interests||[]).join(', ') || 'general sightseeing'}`;
return [{ json: { ...j, groqBody: JSON.stringify({
  model: "openai/gpt-oss-120b",
  messages: [{role:"system", content: system}, {role:"user", content: user}],
  temperature: 0.4, max_tokens: 800, reasoning_effort: "low",
  response_format: {type:"json_object"}
}) } }];

const prev = $('Build Planner Prompt').item.json;
const content = JSON.parse($input.item.json.choices[0].message.content);
return [{ json: { ...prev, planner: { days: content.days || [] } } }];

const j = $input.item.json;
const days = (j.planner && j.planner.days) || [];
const system = "You are the budget checking agent in a trip-planning system for Indian travelers. Given an origin, destination, trip length, number of travelers and target budget, estimate a realistic cost breakdown in INR for the WHOLE GROUP together. Transport and food scale per traveler (each person needs their own seat/meal); lodging usually does not scale linearly since travelers can share rooms - use judgement (e.g. 2 people can often share one room, so lodging for 2 isn't simply double that for 1). Transport must include a ROUND TRIP (there and back) for every traveler, not just one leg for one person. Be realistic even if the target budget is unrealistically low or high for the trip - do not distort your estimate to force it to fit the target. Respond with ONLY JSON: {\"currency\": \"INR\", \"estimatedTotal\": number, \"breakdown\": {\"transport\": number, \"lodging\": number, \"food\": number, \"activities\": number}, \"withinBudget\": boolean, \"note\": \"one short sentence\"}";
const user = `Origin: ${j.origin}\nDestination: ${j.destination}\nTrip length: ${days.length} days\nNumber of travelers: ${j.travelers}\nTarget budget for the whole group (INR): ${j.budget || 'not specified, suggest a reasonable mid-range budget in INR'}`;
return [{ json: { ...j, groqBody: JSON.stringify({
  model: "openai/gpt-oss-120b",
  messages: [{role:"system", content: system}, {role:"user", content: user}],
  temperature: 0.3, max_tokens: 500, reasoning_effort: "low",
  response_format: {type:"json_object"}
}) } }];

const prev = $('Build Budget Prompt').item.json;
const content = JSON.parse($input.item.json.choices[0].message.content);
if (prev.budget) {
  const total = parseFloat(content.estimatedTotal || 0);
  const target = parseFloat(prev.budget);
  if (!isNaN(total) && !isNaN(target)) content.withinBudget = total <= target;
}
return [{ json: { ...prev, budget_result: content } }];

const prev = $('Parse Budget').item.json;
const results = $input.item.json.results || [];
const indiaMatch = results.find(r => r.country === 'India');
const best = indiaMatch || results[0];
const coords = best ? { lat: best.latitude, lon: best.longitude } : null;
return [{ json: { ...prev, coordinates: coords } }];

const prev = $('Parse Geocode').item.json;
const daily = $input.item.json.daily || {};
return [{ json: { ...prev, weather: daily } }];

const j = $input.item.json;
const system = "You are the local info agent in a trip-planning system. Given a destination and interests, suggest 6 to 10 specific, real attractions (not generic categories) and 5 to 6 short, practical local tips. Respond with ONLY JSON: {\"attractions\": [{\"name\": \"...\", \"why\": \"short reason\"}], \"tips\": [\"short practical tip\", \"...\"]}";
const user = `Destination: ${j.destination}\nInterests: ${(j.interests||[]).join(', ') || 'general sightseeing'}`;
return [{ json: { ...j, groqBody: JSON.stringify({
  model: "openai/gpt-oss-120b",
  messages: [{role:"system", content: system}, {role:"user", content: user}],
  temperature: 0.5, max_tokens: 1200, reasoning_effort: "low",
  response_format: {type:"json_object"}
}) } }];

const prev = $('Build LocalInfo Prompt').item.json;
const content = JSON.parse($input.item.json.choices[0].message.content);
const local_info = { attractions: content.attractions || [], tips: content.tips || [], weather: prev.weather, coordinates: prev.coordinates };
return [{ json: { ...prev, local_info } }];

const j = $input.item.json;
const system = "You are the transport agent in a trip-planning system for Indian travelers. Given an origin, destination and number of travelers, list realistic ways to make that journey - choose from flight, train, bus, self-drive/car, whichever are actually practical for this specific route. The costRange for each option must be the ROUND TRIP cost for ALL travelers combined (not one leg, not one person) - state this clearly, e.g. 'round trip for 3 travelers'. Self-drive/car cost does not multiply per traveler (it's one vehicle) - only flight/train/bus costs scale with traveler count. Give an approximate travel duration for one leg. Respond with ONLY JSON: {\"options\": [{\"mode\": \"Flight\", \"costRange\": \"₹3,500–₹6,000 round trip\", \"duration\": \"1h 30m\", \"note\": \"short practical note\"}], \"recommended\": \"one short sentence recommending the best option and why\"}";
const user = `Origin: ${j.origin}\nDestination: ${j.destination}\nNumber of travelers: ${j.travelers}`;
return [{ json: { ...j, groqBody: JSON.stringify({
  model: "openai/gpt-oss-120b",
  messages: [{role:"system", content: system}, {role:"user", content: user}],
  temperature: 0.4, max_tokens: 600, reasoning_effort: "low",
  response_format: {type:"json_object"}
}) } }];

const prev = $('Build Transport Prompt').item.json;
const content = JSON.parse($input.item.json.choices[0].message.content);
return [{ json: { ...prev, transport: content } }];

const j = $input.item.json;
const system = "You are the final itinerary writer agent in a trip-planning system for Indian travelers. Combine the rough day-by-day plan, the budget estimate, the local info and the transport options into one detailed, polished itinerary for the whole group of travelers, all costs in INR representing the group total (not per-person unless stated). The ENTIRE trip takes place in and around the destination city only - never plan days around other cities or a multi-city road trip, even if one would be geographically plausible; only the first day (arrival) and last day (departure) mention travel. Transport cost in the budget breakdown must be the ROUND TRIP cost. For each day, write 4 to 6 specific activities using real place names drawn from the local info provided (attractions, markets, food spots), each prefixed with a time of day where it makes sense, e.g. 'Morning: Visit X and explore the old bazaar.' Spread the attractions and tips across the days rather than reusing the same one or two repeatedly. Respond with ONLY JSON: {\"origin\": \"...\", \"destination\": \"...\", \"days\": [{\"date\": \"YYYY-MM-DD\", \"title\": \"...\", \"activities\": [\"...\", \"...\"]}], \"budget\": {\"currency\": \"INR\", \"estimatedTotal\": number, \"breakdown\": {\"transport\": number, \"lodging\": number, \"food\": number, \"activities\": number}, \"withinBudget\": boolean, \"note\": \"...\"}, \"transport\": {\"options\": [{\"mode\": \"...\", \"costRange\": \"...\", \"duration\": \"...\", \"note\": \"...\"}], \"recommended\": \"...\"}, \"tips\": [\"...\", \"...\"]}";
const user = JSON.stringify({
  origin: j.origin, destination: j.destination, travelers: j.travelers,
  roughPlan: j.planner, budgetEstimate: j.budget_result, localInfo: j.local_info,
  transportOptions: j.transport
});
return [{ json: { ...j, groqBody: JSON.stringify({
  model: "openai/gpt-oss-120b",
  messages: [{role:"system", content: system}, {role:"user", content: user}],
  temperature: 0.4, max_tokens: 5000, reasoning_effort: "low",
  response_format: {type:"json_object"}
}) } }];

const prev = $('Build Writer Prompt').item.json;
const itinerary = JSON.parse($input.item.json.choices[0].message.content);
itinerary.coordinates = prev.local_info ? prev.local_info.coordinates : null;
itinerary.weather = prev.local_info ? prev.local_info.weather : null;
itinerary.attractions = prev.local_info ? prev.local_info.attractions : null;
itinerary.travelers = prev.travelers;
if (!itinerary.origin) itinerary.origin = prev.origin;
if (!itinerary.transport) itinerary.transport = prev.transport;
if (prev.budget && itinerary.budget) {
  const total = parseFloat(itinerary.budget.estimatedTotal || 0);
  const target = parseFloat(prev.budget);
  if (!isNaN(total) && !isNaN(target)) itinerary.budget.withinBudget = total <= target;
}
return [{ json: { trip_id: prev.trip_id, itinerary } }];
